package com.ias.finance;
import org.junit.jupiter.api.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import jakarta.servlet.http.HttpServletRequest;
import com.ias.trust.Problem;
import java.util.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;

class QuoteSourceHttpTest {
 QuoteSourcesTest fixture;MockMvc mvc;FinanceAccess access;
 @BeforeEach void setup()throws Exception{fixture=new QuoteSourcesTest();fixture.setup();access=new FinanceAccess(){public Principal principal(HttpServletRequest r,boolean write){return new Principal(fixture.f.actor,"EMPLOYEE");}public Scope scope(HttpServletRequest r,Principal p,UUID ticket){throw new UnsupportedOperationException();}public FeeGroup.PublishedRule rule(HttpServletRequest r){return fixture.command.rule();}public JdbcFeeGroups.Access bind(HttpServletRequest r,Principal p){return fixture.f.authority;}};mvc=MockMvcBuilders.standaloneSetup(new QuoteSourceController(fixture.f.source,access,r->{if(!r.isSecure()||!"ticket-finance".equals(r.getAttribute("ias.chain.edge")))throw new Problem(403,"SERVICE_AUTHENTICATION_FAILED");})).setControllerAdvice(new FinanceErrors()).build();}
 Map<String,Object> binding(){var b=JdbcQuoteSources.view(new JdbcQuoteSources.Source(JdbcQuoteSources.binding(fixture.f.actor,fixture.f.owner,fixture.command,fixture.details),"IN_PROGRESS",null,fixture.command,fixture.details));b.remove("state");b.remove("sourceState");b.remove("resultDigest");b.put("faultRelationId",fixture.relation.toString());b.put("ticketId",fixture.command.additions().getFirst().ticketId().toString());b.put("roundId",fixture.command.additions().getFirst().roundId().toString());return b;}
 String json(Object value){return FinanceController.JSON.writeValueAsString(value);}
 @Test void trustedSourceQueryIsReadOnlyAndReturnsExactSafeBinding()throws Exception{fixture.register();long operations=fixture.f.count("finance_operation"),events=fixture.f.count("finance_quote_source_event");var result=mvc.perform(post("/internal/finance/quote-sources/query").secure(true).requestAttr("ias.chain.edge","ticket-finance").contentType("application/json").content(json(binding()))).andExpect(status().isOk()).andExpect(jsonPath("$.state").value("IN_PROGRESS")).andExpect(jsonPath("$.actorUserId").value("10")).andExpect(header().string("Cache-Control","no-store")).andReturn().getResponse().getContentAsString();assertFalse(result.contains("pricingDescription")||result.contains("250000")||result.contains("threshold"));assertEquals(operations,fixture.f.count("finance_operation"));assertEquals(events,fixture.f.count("finance_quote_source_event"));}
 @Test void missingQueryIs404AndMismatch409WithoutAbortOrMutation()throws Exception{var body=binding();mvc.perform(post("/internal/finance/quote-sources/query").secure(true).requestAttr("ias.chain.edge","ticket-finance").contentType("application/json").content(json(body))).andExpect(status().isNotFound());assertEquals(0,fixture.f.count("finance_quote_source"));fixture.register();body.put("commandDigest","0".repeat(64));mvc.perform(post("/internal/finance/quote-sources/query").secure(true).requestAttr("ias.chain.edge","ticket-finance").contentType("application/json").content(json(body))).andExpect(status().isConflict());assertEquals("IN_PROGRESS",fixture.sources.read(fixture.f.actor,fixture.f.owner,fixture.command.operationId()).state());}
 @Test void productionGuardRejectsForgedHeadersAndWrongEdgeBeforeReadingFacts()throws Exception{var production=MockMvcBuilders.standaloneSetup(new QuoteSourceController(fixture.f.source,access)).setControllerAdvice(new FinanceErrors()).build();production.perform(post("/internal/finance/quote-sources/query").secure(true).header("X-Internal-Edge","ticket-finance").header("X-User-Id","10").contentType("application/json").content(json(binding()))).andExpect(status().isForbidden());mvc.perform(post("/internal/finance/quote-sources/query").secure(true).requestAttr("ias.chain.edge","gateway-finance").contentType("application/json").content(json(binding()))).andExpect(status().isForbidden());assertEquals(0,fixture.f.count("finance_quote_source"));}
 @Test void explicitAbortUsesOriginalKeyAndLateCommitIsFenced()throws Exception{fixture.register();String base="/api/finance/groups/"+fixture.f.owner.faultGroupId()+"/quote-sources/"+fixture.command.operationId();var body=new HashMap<String,Object>();body.put("operationId",fixture.command.operationId().toString());body.put("quoteId",fixture.command.applicationId().toString());body.put("expectedGroupVersion","0");body.put("commandDigest",JdbcFeeGroups.quoteDigest(fixture.f.owner,fixture.command,fixture.details));body.put("reason","当前用户明确中止原报价源操作");mvc.perform(post(base+"/abort").header("Idempotency-Key",fixture.command.operationId()).contentType("application/json").content(json(body))).andExpect(status().isOk()).andExpect(jsonPath("$.state").value("ABORTED"));mvc.perform(get(base)).andExpect(status().isOk()).andExpect(jsonPath("$.state").value("ABORTED"));assertThrows(IllegalStateException.class,()->fixture.f.store.submit(fixture.f.actor,fixture.f.owner,fixture.command,fixture.details));assertEquals(0,fixture.f.count("finance_quote_version"));}
}
